L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "\229\164\149\227\129\148\233\163\175\227\129\175\227\129\169\227\129\134\227\129\151\227\129\190\227\129\153\239\188\159\227\128\128\233\163\159\227\129\185\227\129\166\227\129\139\227\130\137\229\184\176\233\130\132\227\129\151\227\129\190\227\129\153\227\129\139\239\188\159\227\128\128\227\129\157\227\130\140\227\129\168\227\130\130\227\128\129\229\184\176\233\130\132\227\129\151\227\129\166\227\129\139\227\130\137\233\163\159\227\129\185\227\129\190\227\129\153\227\129\139\239\188\159"
L7_1.m_Talk_JPN = L8_1
L8_1 = "What are we going to do about dinner? Should we eat out, or should we go back first?"
