L8_1 = "\230\153\154\233\164\144\232\166\129\230\128\142\233\186\188\232\167\163\230\177\186\239\188\159\230\152\175\229\144\131\229\174\140\229\134\141\229\155\158\229\142\187\229\151\142\239\188\159\233\130\132\230\152\175\229\155\158\229\142\187\229\190\140\229\134\141\229\144\131\239\188\159"
