L8_1 = "B\225\187\175a t\225\187\145i th\195\172 sao? Ch\195\186ng ta n\195\170n \196\131n ngo\195\160i, hay n\195\170n v\225\187\129 tr\198\176\225\187\155c?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "\230\153\154\233\165\173\232\166\129\230\128\142\228\185\136\232\167\163\229\134\179\239\188\159\230\152\175\229\144\131\229\174\140\229\134\141\229\155\158\229\142\187\229\144\151\239\188\159\232\191\152\230\152\175\229\155\158\229\142\187\229\134\141\229\144\131\239\188\159"
